import{_ as s,o as t,c as n,a5 as r}from"./chunks/framework.CXroN2RO.js";const p=JSON.parse('{"title":"最終章 ボタンを押してから画面に出るまで","description":"","frontmatter":{"title":"最終章 ボタンを押してから画面に出るまで","study":{"source":"IT教本","status":"outline","summary":"これまでの層を一つの流れに結び付け、説明と観察をやり直すための学習計画・概要です。下の時系列は理解を助ける説明モデルで、すべての機器・OS・エンジンが同じ経路や時間で動くことを示すものではありません。\\n\\n## 関連する辞典本文・実践\\n\\n- [Game Loop](/game/patterns","section":"learning","format":"path","domain":"game","collection":"low-level","order":20}},"headers":[],"relativePath":"guide/low-level/button-to-screen.md","filePath":"guide/low-level/button-to-screen.md"}'),o={name:"guide/low-level/button-to-screen.md"};function e(l,a,i,h,d,g){return t(),n("div",null,[...a[0]||(a[0]=[r(`<div id="最終章-ボタンを押してから画面に出るまで-──-全章統合・1フレームの完全な旅" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="最終章-ボタンを押してから画面に出るまで" tabindex="-1">最終章 ボタンを押してから画面に出るまで <a class="header-anchor" href="#最終章-ボタンを押してから画面に出るまで" aria-label="Permalink to &quot;最終章 ボタンを押してから画面に出るまで&quot;">​</a></h1><h2 id="このページで案内すること" tabindex="-1">このページで案内すること <a class="header-anchor" href="#このページで案内すること" aria-label="Permalink to &quot;このページで案内すること&quot;">​</a></h2><p>これまでの層を一つの流れに結び付け、説明と観察をやり直すための<strong>学習計画・概要</strong>です。下の時系列は理解を助ける説明モデルで、すべての機器・OS・エンジンが同じ経路や時間で動くことを示すものではありません。</p><h2 id="関連する辞典本文・実践" tabindex="-1">関連する辞典本文・実践 <a class="header-anchor" href="#関連する辞典本文・実践" aria-label="Permalink to &quot;関連する辞典本文・実践&quot;">​</a></h2><ul><li><a href="/study/game/patterns/game-loop-and-update.html">Game Loop</a>、<a href="/study/runtime/cpp-internals/build-pipeline-journey.html">ビルドの流れ</a>、<a href="/study/graphics/pipeline/overview.html">レンダリングパイプライン</a>で、不明な段階へ戻れます。</li><li><a href="/study/game/shooter-design.html">小さなシューティング</a>は、入力・状態更新・描画をコード上で対応させる実践例です。</li></ul><h2 id="この章の目的" tabindex="-1">この章の目的 <a class="header-anchor" href="#この章の目的" aria-label="Permalink to &quot;この章の目的&quot;">​</a></h2><p>この章では、新しい話題を広げるより、 <strong>ここまでの各章を1本のストーリーにつなぎ、理解できた部分と さらに調べたい部分を確認する</strong>。</p><p>以下の物語を読み、<strong>自分の実装ではどうなっているかを説明する</strong>練習に使ってください。</p><hr><h2 id="一連の流れ-──-アクションゲームで「ジャンプボタンを押す」" tabindex="-1">一連の流れ ── アクションゲームで「ジャンプボタンを押す」 <a class="header-anchor" href="#一連の流れ-──-アクションゲームで「ジャンプボタンを押す」" aria-label="Permalink to &quot;一連の流れ ── アクションゲームで「ジャンプボタンを押す」&quot;">​</a></h2><h3 id="第1幕-指がボタンを押す-0ms" tabindex="-1">第1幕 指がボタンを押す(0ms) <a class="header-anchor" href="#第1幕-指がボタンを押す-0ms" aria-label="Permalink to &quot;第1幕 指がボタンを押す(0ms)&quot;">​</a></h3><ol><li>親指がボタンを押し込み、<strong>物理接点が閉じて電気が流れる</strong>。[第1,2章]</li><li>パッド内のマイコンが数ms周期でボタンマトリクスをスキャンし、 状態変化を検出。<strong>ボタン状態はビットフラグ</strong>として HIDレポートにパックされる。[第1章: ビット表現]</li><li>USBはホスト主導。PCのUSBホストコントローラが<strong>1〜8ms周期の ポーリング</strong>でレポートを回収する(無線ならBTスタック経由)。[第8章]</li></ol><h3 id="第2幕-osの中を通る-1〜8ms" tabindex="-1">第2幕 OSの中を通る(+1〜8ms) <a class="header-anchor" href="#第2幕-osの中を通る-1〜8ms" aria-label="Permalink to &quot;第2幕 OSの中を通る(+1〜8ms)&quot;">​</a></h3><ol start="4"><li>USBコントローラが受信を<strong>割り込み</strong>でCPUに通知。CPUは実行中の 処理を中断してカーネルモードへ遷移、割り込みハンドラ→ HIDクラスドライバがレポートを解析し、XInput/GameInputの デバイス状態として保持する。[第8章: 割り込み・ドライバ・特権モード]</li><li>この間もゲームプロセスは自分の<strong>仮想アドレス空間</strong>で走り続けている。 OSのスケジューラが各スレッドをコアに割り当てている。[第8章]</li></ol><h3 id="第3幕-ゲームループが入力を拾う-次のフレーム頭" tabindex="-1">第3幕 ゲームループが入力を拾う(次のフレーム頭) <a class="header-anchor" href="#第3幕-ゲームループが入力を拾う-次のフレーム頭" aria-label="Permalink to &quot;第3幕 ゲームループが入力を拾う(次のフレーム頭)&quot;">​</a></h3><ol start="6"><li>ゲームのメインスレッドがフレーム先頭で <code>XInputGetState()</code> を呼ぶ。 これは<strong>DLLの関数</strong>(第7章: インポートテーブル経由)であり、 内部でドライバの保持する状態を読み出す。</li><li>入力システムが前フレームとのXORで<strong>エッジ検出</strong>: 「Aボタンが今フレーム押された」。論理アクション「ジャンプ」に変換され、 先行入力バッファに積まれる。[第14章]</li></ol><h3 id="第4幕-ゲームロジックが世界を進める-0〜16ms" tabindex="-1">第4幕 ゲームロジックが世界を進める(+0〜16ms) <a class="header-anchor" href="#第4幕-ゲームロジックが世界を進める-0〜16ms" aria-label="Permalink to &quot;第4幕 ゲームロジックが世界を進める(+0〜16ms)&quot;">​</a></h3><ol start="8"><li><strong>固定タイムステップ</strong>の更新が回る。ジャンプ入力を消費し、 プレイヤーの速度Yに初速が入る。この1行のC++は、コンパイラが 生成した<strong>機械語</strong>(例えばmov/addss。最適化やCPUで変わる)として、CPUが<strong>キャッシュ</strong>から データを引きつつ実行する。[第2〜5,9章]</li><li>物理システムが全エンティティを更新。<strong>ECS</strong>なら速度・位置 コンポーネントが<strong>連続メモリ</strong>に並び、キャッシュラインを 無駄なく舐める。空間グリッドで衝突候補を絞り、AABB判定。 [第3,10,15章]</li><li>この物理・アニメ・AI更新は<strong>ジョブシステム</strong>でワーカースレッドに 分配され、依存関係と利用可能なCPUに応じて並列に進む。必要な同期は ジョブシステムが管理し、worker数がそのまま同時実行数になるとは限らない。[第8章]</li><li>アニメーションシステムがジャンプモーションへ遷移し、 <strong>クォータニオンslerp</strong>でポーズをブレンド、ボーン行列を計算。[第10章]</li><li>この間、メモリ確保は<strong>フレームアロケータ/プール</strong>から行われ、 汎用mallocはほぼ呼ばれない。[第6章]</li></ol><h3 id="第5幕-描画コマンドを作る-同フレーム後半" tabindex="-1">第5幕 描画コマンドを作る(同フレーム後半) <a class="header-anchor" href="#第5幕-描画コマンドを作る-同フレーム後半" aria-label="Permalink to &quot;第5幕 描画コマンドを作る(同フレーム後半)&quot;">​</a></h3><ol start="13"><li>カメラの<strong>ビュー行列・射影行列</strong>を構築。<strong>フラスタムカリング</strong>で 見えないオブジェクトを捨てる。[第10章]</li><li>残った描画物をマテリアル・深度で<strong>ソート</strong>し、レンダラが パス(シャドウ→不透明→スカイ→半透明→ポスト)を組み立てる。 UEならこれは<strong>レンダースレッド</strong>の仕事(1フレーム遅れの並走)。[第15,17章]</li><li>RHI/抽象化層が<strong>コマンドリスト</strong>に記録: バリア、PSO設定、 ディスクリプタ、定数バッファ更新(MVP行列・ボーン行列)、 DrawIndexedInstanced。<code>ExecuteCommandLists</code>で<strong>キューへ提出</strong>。 ドライバがGPU固有コマンドへ変換し、<strong>DMA</strong>でGPUに届く。[第13章]</li></ol><h3 id="第6幕-gpuが絵を作る-1フレーム、16ms" tabindex="-1">第6幕 GPUが絵を作る(+1フレーム、16ms) <a class="header-anchor" href="#第6幕-gpuが絵を作る-1フレーム、16ms" aria-label="Permalink to &quot;第6幕 GPUが絵を作る(+1フレーム、16ms)&quot;">​</a></h3><ol start="16"><li>GPUのフロントエンドがコマンドを読み、<strong>頂点シェーダ</strong>を起動。 数千のALUが<strong>ワープ/ウェーブ単位</strong>で頂点を並列処理: <code>mul(pos, MVP)</code> ── ジャンプで上がったY座標がここでスクリーン 空間へ写る。スキニングならボーン行列で頂点が変形。[第10,11,12章]</li><li><strong>ラスタライザ</strong>(固定機能)が三角形をピクセルに分解、属性を 透視補正<strong>補間</strong>。<strong>ピクセルシェーダ</strong>がテクスチャを サンプリング(<strong>ミップマップ</strong>でキャッシュ・帯域を節約)し、 法線と光の<strong>内積</strong>でライティング。[第11,12章]</li><li><strong>出力マージャ</strong>が深度テストで前後関係を解決し、ブレンドして **フレームバッファ(VRAM)**へ書き込む。ポストプロセス (トーンマップ・ブルーム・AA)がフルスクリーンパスで走る。[第12章]</li></ol><h3 id="第7幕-画面に光る-1〜2フレーム" tabindex="-1">第7幕 画面に光る(+1〜2フレーム) <a class="header-anchor" href="#第7幕-画面に光る-1〜2フレーム" aria-label="Permalink to &quot;第7幕 画面に光る(+1〜2フレーム)&quot;">​</a></h3><ol start="19"><li><code>Present()</code>。<strong>スワップチェーン</strong>のバックバッファが表示候補になり、 VSyncならディスプレイの垂直帰線を待って<strong>フリップ</strong>。[第13章]</li><li>ディスプレイコントローラがフレームバッファを<strong>スキャンアウト</strong>し、 ケーブル経由でパネルへ。液晶が応答し、光が目に届く。</li><li><strong>合計: ボタンから光まで約30〜80ms</strong>。内訳(パッド+OS+ ループ待ち+更新+GPU+表示)をあなたはもう全部言える。[第14章]</li></ol><h3 id="第8幕-それを見ているもう一人の自分" tabindex="-1">第8幕 それを見ているもう一人の自分 <a class="header-anchor" href="#第8幕-それを見ているもう一人の自分" aria-label="Permalink to &quot;第8幕 それを見ているもう一人の自分&quot;">​</a></h3><ol start="22"><li>Tracyにはこのフレームの区間が、RenderDocにはドローコール列が、 VSには機械語とメモリが見えている。<strong>問題が起きた段階に合う道具を選び、 観測結果から仮説を検証する</strong>ことを目指す。[第18章]</li></ol><hr><h2 id="卒業課題" tabindex="-1">卒業課題 <a class="header-anchor" href="#卒業課題" aria-label="Permalink to &quot;卒業課題&quot;">​</a></h2><ol><li><strong>口頭試問(セルフ)</strong>: 上の22ステップを、何も見ずにホワイトボードに 図解しながら15分で説明せよ。詰まった幕の章に戻れ。</li><li><strong>物証を集める</strong>: 各幕に対応する「実物のスクリーンショット」を 自分で撮って1つのドキュメントにせよ: <ul><li>第3幕: XInputポーリングのコールスタック(VS)</li><li>第4幕: 更新処理の逆アセンブリとキャッシュミス計測</li><li>第5幕: コマンドリスト記録のAPIログ(PIX)</li><li>第6幕: RenderDocの頂点入力→VS出力→PS出力</li><li>第7幕: Presentのタイムライン(PIX)と高速カメラでの遅延実測</li></ul></li><li><strong>自作エンジンで再現</strong>: 第15章のミニエンジンに、この旅の全幕が 存在することを確認し、READMEに「自分のエンジンの1フレーム」として 同じ物語を書け。</li><li><strong>他人に教える</strong>: 後輩(または勉強会)に90分でこの物語を講義せよ。 説明が詰まる箇所や質問された箇所を、次に調べる課題として記録する。</li></ol><hr><h2 id="この教本全体の地図-再掲・完成版" tabindex="-1">この教本全体の地図(再掲・完成版) <a class="header-anchor" href="#この教本全体の地図-再掲・完成版" aria-label="Permalink to &quot;この教本全体の地図(再掲・完成版)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>指 → パッド(1,2章) → USB/割り込み/ドライバ(8章) → 入力API(8,14章)</span></span>
<span class="line"><span> → ゲームループ(14章)</span></span>
<span class="line"><span>    ├─ C++/機械語として実行(4,5,6,7,9章)</span></span>
<span class="line"><span>    ├─ CPU/キャッシュの上で(2,3章)</span></span>
<span class="line"><span>    ├─ ECS/エンジンの構造で(15章) ── Unity(16章)/UE5(17章)</span></span>
<span class="line"><span>    ├─ 数学で世界を記述(10章)</span></span>
<span class="line"><span>    └─ ジョブで並列化(8章)</span></span>
<span class="line"><span> → 描画コマンド(13章) → GPU(11章) → パイプライン(12章)</span></span>
<span class="line"><span> → Present/スキャンアウト(13章) → 目</span></span>
<span class="line"><span>      全区間を観測: デバッガ/プロファイラ(18章)</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://eel.is/c++draft/intro.abstract" target="_blank" rel="noreferrer">C++ working draft: Abstract machine</a></li><li><a href="https://learn.microsoft.com/en-us/windows/win32/procthread/scheduling-priorities" target="_blank" rel="noreferrer">Microsoft: Scheduling Priorities</a></li></ul>`,35)])])}const u=s(o,[["render",e]]);export{p as __pageData,u as default};
